using System;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>One four-sided facade piece cut from a surface.</summary>
    public class Panel
    {
        public Panel(Point3d a, Point3d b, Point3d c, Point3d d, int index)
        {
            Corners = new[] { a, b, c, d };
            Index = index;
            Outline = new PolylineCurve(new[] { a, b, c, d, a });
            Area = 0.5 * Vector3d.CrossProduct(c - a, d - b).Length;
            Deviation = ComputeDeviation(a, b, c, d);
        }

        public Point3d[] Corners { get; }
        public PolylineCurve Outline { get; }
        public double Area { get; }
        public double Deviation { get; }
        public int Index { get; }

        public Point3d Center => new Point3d(
            (Corners[0].X + Corners[1].X + Corners[2].X + Corners[3].X) / 4.0,
            (Corners[0].Y + Corners[1].Y + Corners[2].Y + Corners[3].Y) / 4.0,
            (Corners[0].Z + Corners[1].Z + Corners[2].Z + Corners[3].Z) / 4.0);

        /// <summary>Length of edge i (0 = first corner to second, ..., 3 = fourth back to first).</summary>
        public double Edge(int i) => Corners[i].DistanceTo(Corners[(i + 1) % 4]);

        public double Diagonal(int i) => Corners[i].DistanceTo(Corners[i + 2]);

        /// <summary>Mean of first and third edge lengths.</summary>
        public double Width => 0.5 * (Edge(0) + Edge(2));

        /// <summary>Mean of second and fourth edge lengths.</summary>
        public double Height => 0.5 * (Edge(1) + Edge(3));

        private static double ComputeDeviation(Point3d a, Point3d b, Point3d c, Point3d d)
        {
            Vector3d n = Vector3d.CrossProduct(b - a, c - a);
            if (!n.Unitize())
                return 0.0;
            return Math.Abs((d - a) * n);
        }
    }
}
EOF
