using System;
using System.Collections.Generic;
using System.Linq;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade
{
    public class PlanarityComponent : PanelComponent
    {
        public PlanarityComponent()
            : base("Planarity", "Planarity", "Measures how far each panel is from flat", "Analysis")
        {
        }

        public override Guid ComponentGuid => new Guid("3d806cb2-7e49-4fa1-85a3-9142eb36d003");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            AddPanelsInput(pManager, "Panels");
            pManager.AddNumberParameter("Tolerance", "T", "Largest deviation still counted as flat", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Deviation", "D", "Planarity deviation per panel", GH_ParamAccess.list);
            pManager.AddBooleanParameter("Flat", "F", "True where Deviation is at most Tolerance", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Flat Count", "N", "Number of flat panels", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            double tolerance = 0.5;
            if (!DA.GetData(1, ref tolerance)) return;
            List<Panel> panels = GetPanels(DA, 0);

            var deviation = panels.Select(p => p.Deviation).ToList();
            var flat = panels.Select(p => p.Deviation <= tolerance).ToList();
            int flatCount = flat.Count(f => f);
            int notFlat = panels.Count - flatCount;

            if (notFlat * 2 > panels.Count)
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                    notFlat + " of " + panels.Count + " panels are not flat.");

            DA.SetDataList(0, deviation);
            DA.SetDataList(1, flat);
            DA.SetData(2, flatCount);
        }
    }

    public class ClassifyPanelsComponent : PanelComponent
    {
        public ClassifyPanelsComponent()
            : base("Classify Panels", "Classify", "Classifies panels as flat, cold-bent or custom", "Analysis")
        {
        }

        public override Guid ComponentGuid => new Guid("4e917dc3-8f5a-40b2-96b4-a253fc47e104");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            AddPanelsInput(pManager, "Panels");
            pManager.AddNumberParameter("Tolerance", "T", "Flat tolerance; cold-bent allows 10 times this", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("Type", "T", "flat, cold-bent or custom per panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Flat Count", "F", "Number of flat panels", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Cold Bent Count", "C", "Number of cold-bent panels", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Custom Count", "U", "Number of custom panels", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            double tolerance = 0.5;
            if (!DA.GetData(1, ref tolerance)) return;
            List<Panel> panels = GetPanels(DA, 0);

            var types = new List<string>(panels.Count);
            int flat = 0, coldBent = 0, custom = 0;
            foreach (Panel p in panels)
            {
                if (p.Deviation <= tolerance) { types.Add("flat"); flat++; }
                else if (p.Deviation <= 10.0 * tolerance) { types.Add("cold-bent"); coldBent++; }
                else { types.Add("custom"); custom++; }
            }

            DA.SetDataList(0, types);
            DA.SetData(1, flat);
            DA.SetData(2, coldBent);
            DA.SetData(3, custom);
        }
    }

    public class PanelStatsComponent : PanelComponent
    {
        public PanelStatsComponent()
            : base("Panel Stats", "Stats", "Area statistics of a set of panels", "Analysis")
        {
        }

        public override Guid ComponentGuid => new Guid("5fa28ed4-906b-41c3-a7c5-b364ad58f205");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            AddPanelsInput(pManager, "Panels");
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Total Area", "T", "Sum of panel areas", GH_ParamAccess.item);
            pManager.AddNumberParameter("Min Area", "Min", "Smallest panel area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Max Area", "Max", "Largest panel area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Mean Area", "Mean", "Mean panel area", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            List<Panel> panels = GetPanels(DA, 0);
            if (panels.Count == 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "No panels.");
                return;
            }

            double total = panels.Sum(p => p.Area);
            DA.SetData(0, total);
            DA.SetData(1, panels.Min(p => p.Area));
            DA.SetData(2, panels.Max(p => p.Area));
            DA.SetData(3, total / panels.Count);
        }
    }
}

