            int flat = 0, coldBent = 0, custom = 0;
            foreach (Panel p in panels)
            {
                if (p.Deviation <= tolerance) { types.Add("flat"); flat++; }
                else if (p.Deviation <= 10.0 * tolerance) { types.Add("cold-bent"); coldBent++; }
                else { types.Add("custom"); custom++; }
            }

            DA.SetDataList(0, types);
            DA.SetData(1, flat);
            DA.SetData(2, coldBent);
            DA.SetData(3, custom);
