        {
            AddPanelsInput(pManager, "Panels");
            pManager.AddNumberParameter("Tolerance", "T", "Largest allowed difference in any length", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddIntegerParameter("Group", "G", "Group number per panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Group Count", "N", "Number of groups", GH_ParamAccess.item);
            pManager.AddParameter(new PanelParam(), "Representatives", "R", "First panel of each group", GH_ParamAccess.list);
        }

        private static double[] Signature(Panel p)
        {
            var edges = new[] { p.Edge(0), p.Edge(1), p.Edge(2), p.Edge(3) };
            var diagonals = new[] { p.Diagonal(0), p.Diagonal(1) };
            Array.Sort(edges);
            Array.Sort(diagonals);
            return edges.Concat(diagonals).ToArray();
        }

        private static bool Matches(double[] a, double[] b, double tolerance)
        {
            for (int i = 0; i < a.Length; i++)
                if (Math.Abs(a[i] - b[i]) > tolerance)
                    return false;
            return true;
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            double tolerance = 1.0;
            if (!DA.GetData(1, ref tolerance)) return;
            List<Panel> panels = GetPanels(DA, 0);

            var groups = new List<int>(panels.Count);
            var reps = new List<PanelGoo>();
            var repSignatures = new List<double[]>();
            foreach (Panel p in panels)
            {
                double[] sig = Signature(p);
                int g = repSignatures.FindIndex(r => Matches(r, sig, tolerance));
                if (g < 0)
                {
                    g = repSignatures.Count;
                    repSignatures.Add(sig);
                    reps.Add(new PanelGoo(p));
                }
                groups.Add(g);
            }

            DA.SetDataList(0, groups);
            DA.SetData(1, reps.Count);
            DA.SetDataList(2, reps);
        }
    }

    public class CutListComponent : PanelComponent
    {
        public CutListComponent()
            : base("Cut List", "CutList", "Builds a CSV cut list and optionally writes it to a file", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("71c4a0f6-b28d-43e5-89e7-d586cf7ab407");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            AddPanelsInput(pManager, "Panels");
            pManager.AddTextParameter("Path", "Path", "File to write the CSV to", GH_ParamAccess.item, "");
            pManager.AddBooleanParameter("Write", "W", "Write the file when true", GH_ParamAccess.item, false);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("CSV", "CSV", "Cut list as CSV text", GH_ParamAccess.item);
            pManager.AddBooleanParameter("Written", "W", "True if the file was written", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            string path = "";
            bool write = false;
            DA.GetData(1, ref path);
            if (!DA.GetData(2, ref write)) return;
            List<Panel> panels = GetPanels(DA, 0);

            var inv = CultureInfo.InvariantCulture;
            var sb = new StringBuilder("Index,Width,Height,Area,Deviation\n");
            foreach (Panel p in panels)
                sb.Append(p.Index.ToString(inv)).Append(',')
                  .Append(p.Width.ToString("R", inv)).Append(',')
                  .Append(p.Height.ToString("R", inv)).Append(',')
                  .Append(p.Area.ToString("R", inv)).Append(',')
                  .Append(p.Deviation.ToString("R", inv)).Append('\n');
            string csv = sb.ToString();

            bool written = false;
            if (write)
            {
                if (string.IsNullOrWhiteSpace(path))
                {
                    AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Write is true but Path is empty.");
                }
                else
                {
                    try
                    {
                        File.WriteAllText(path, csv);
                        written = true;
                    }
                    catch (Exception e)
                    {
                        AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Could not write file: " + e.Message);
                    }
                }
            }

            DA.SetData(0, csv);
            DA.SetData(1, written);
        }
    }
}

