using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    public class NestOnSheetsComponent : PanelComponent
    {
        private sealed class NestResult
        {
            public List<Panel> Panels;
            public double Width, Height, Spacing;
            public List<Rectangle3d> Rects = new List<Rectangle3d>();
            public List<int> Sheets = new List<int>();
            public int SheetCount;
            public int Unplaced;
            public double PlacedArea;
        }

        private CancellationTokenSource _cts;
        private NestResult _ready;

        public NestOnSheetsComponent()
            : base("Nest On Sheets", "Nest", "Nests panels as rectangles on sheets with a shelf algorithm", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("82d5b107-c39e-44f6-9af8-e697d08bc508");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            AddPanelsInput(pManager, "Panels");
            pManager.AddNumberParameter("Sheet Width", "W", "Sheet width", GH_ParamAccess.item, 3000.0);
            pManager.AddNumberParameter("Sheet Height", "H", "Sheet height", GH_ParamAccess.item, 1500.0);
            pManager.AddNumberParameter("Spacing", "S", "Gap between parts and from the sheet edge", GH_ParamAccess.item, 10.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddCurveParameter("Outlines", "O", "Placed rectangles", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet", "S", "Sheet index of each placed panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet Count", "N", "Number of sheets used", GH_ParamAccess.item);
            pManager.AddNumberParameter("Utilization", "U", "Placed area over total sheet area", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            double width = 3000, height = 1500, spacing = 10;
            if (!DA.GetData(1, ref width)) return;
            if (!DA.GetData(2, ref height)) return;
            if (!DA.GetData(3, ref spacing)) return;
            List<Panel> panels = GetPanels(DA, 0);

            NestResult ready = _ready;
            if (ready != null && ready.Width == width && ready.Height == height && ready.Spacing == spacing
                && ready.Panels.SequenceEqual(panels))
            {
                _ready = null;
                Message = "";
                if (ready.Unplaced > 0)
                    AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                        ready.Unplaced + " panels do not fit on any sheet.");
                double sheetArea = ready.SheetCount * width * height;
                DA.SetDataList(0, ready.Rects.Select(r => (Curve)r.ToNurbsCurve()));
                DA.SetDataList(1, ready.Sheets);
                DA.SetData(2, ready.SheetCount);
                DA.SetData(3, sheetArea > 0 ? ready.PlacedArea / sheetArea : 0.0);
                return;
            }

            // Inputs changed or first run: stop the old run and start a new one.
            _ready = null;
            _cts?.Cancel();
            var cts = new CancellationTokenSource();
            _cts = cts;
            Message = "Nesting 0%";

            var sizes = panels.Select(p => (w: p.Width, h: p.Height)).ToList();
            GH_Document doc = OnPingDocument();
            Task.Run(() =>
            {
                NestResult result = Nest(sizes, width, height, spacing, cts.Token, pct =>
                    ReportProgress(cts, "Nesting " + pct + "%"));
                if (result == null || cts.IsCancellationRequested) return;
                result.Panels = panels;
                result.Width = width;
                result.Height = height;
                result.Spacing = spacing;
                _ready = result;
                doc?.ScheduleSolution(5, d =>
                {
                    if (!cts.IsCancellationRequested) ExpireSolution(false);
                });
            }, cts.Token);
        }

        private void ReportProgress(CancellationTokenSource cts, string text)
        {
            if (cts.IsCancellationRequested) return;
            var canvas = Grasshopper.Instances.ActiveCanvas;
            if (canvas == null || canvas.IsDisposed) return;
            canvas.BeginInvoke((Action)(() =>
            {
                if (cts.IsCancellationRequested) return;
                Message = text;
                OnDisplayExpired(false);
            }));
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            _cts?.Cancel();
            base.RemovedFromDocument(document);
        }

        private static NestResult Nest(List<(double w, double h)> sizes, double sheetW, double sheetH,
            double gap, CancellationToken token, Action<int> progress)
        {
            var result = new NestResult();
            // Tallest first.
            var order = Enumerable.Range(0, sizes.Count).OrderByDescending(i => sizes[i].h).ToList();

            int sheet = -1;
            double x = 0, shelfY = 0, shelfH = 0;
            bool haveShelf = false;
            int lastPct = -1;

            for (int n = 0; n < order.Count; n++)
            {
                if (token.IsCancellationRequested) return null;
                int pct = (int)(100.0 * n / order.Count);
                if (pct != lastPct && pct % 5 == 0) { lastPct = pct; progress(pct); }

                (double w, double h) = sizes[order[n]];
                var orientations = new[] { (w, h), (h, w) };

                double pw = 0, ph = 0;
                bool placed = false;

                // 1. Current shelf.
                if (haveShelf)
                {
                    foreach (var (ow, oh) in orientations)
                    {
                        if (x + ow + gap <= sheetW && oh <= shelfH)
                        {
                            pw = ow; ph = oh; placed = true;
                            break;
                        }
                    }
                }

                // 2. New shelf above on the current sheet.
                if (!placed && haveShelf)
                {
                    double newY = shelfY + shelfH + gap;
                    foreach (var (ow, oh) in orientations)
                    {
                        if (gap + ow + gap <= sheetW && newY + oh + gap <= sheetH)
                        {
                            pw = ow; ph = oh; placed = true;
                            shelfY = newY; shelfH = oh; x = gap;
                            break;
                        }
                    }
                }

                // 3. New sheet.
                if (!placed)
                {
                    foreach (var (ow, oh) in orientations)
                    {
                        if (gap + ow + gap <= sheetW && gap + oh + gap <= sheetH)
                        {
                            pw = ow; ph = oh; placed = true;
                            sheet++;
                            haveShelf = true;
                            shelfY = gap; shelfH = oh; x = gap;
                            break;
                        }
                    }
                }

                if (!placed)
                {
                    result.Unplaced++;
                    continue;
                }

                double originX = sheet * (sheetW + 100.0);
                var plane = new Plane(new Point3d(originX + x, shelfY, 0), Vector3d.ZAxis);
                result.Rects.Add(new Rectangle3d(plane, pw, ph));
                result.Sheets.Add(sheet);
                result.PlacedArea += pw * ph;
                x += pw + gap;
            }

            result.SheetCount = sheet + 1;
            progress(100);
            return result;
        }
    }
}

