                {
                    foreach (var (ow, oh) in orientations)
                    {
                        if (x + ow + gap <= sheetW && oh <= shelfH)
                        {
                            pw = ow; ph = oh; placed = true;
                            break;
                        }
                    }
                }

                // 2. New shelf above on the current sheet.
