                {
                    double newY = shelfY + shelfH + gap;
                    foreach (var (ow, oh) in orientations)
                    {
                        if (gap + ow + gap <= sheetW && newY + oh + gap <= sheetH)
                        {
                            pw = ow; ph = oh; placed = true;
                            shelfY = newY; shelfH = oh; x = gap;
                            break;
                        }
                    }
                }

                // 3. New sheet.
