using System;
using Grasshopper.Kernel;
using Grasshopper.Kernel.Types;

namespace BenchPlugin.Facade
{
    public class PanelGoo : GH_Goo<Panel>
    {
        public PanelGoo()
        {
        }

        public PanelGoo(Panel panel)
        {
            Value = panel;
        }

        public override bool IsValid => Value != null;
        public override string TypeName => "Panel";
        public override string TypeDescription => "Four-sided facade panel";

        public override IGH_Goo Duplicate() => new PanelGoo(Value);

        public override string ToString() => Value == null
            ? "Null Panel"
            : $"Panel {Value.Index} (area {Value.Area:0.###}, deviation {Value.Deviation:0.###})";

        public override bool CastFrom(object source)
        {
            if (source is Panel p)
            {
                Value = p;
                return true;
            }
            if (source is PanelGoo g)
            {
                Value = g.Value;
                return true;
            }
            return false;
        }
    }

    public class PanelParam : GH_Param<PanelGoo>
    {
        public PanelParam()
            : base("Panel", "Panel", "Facade panel", "Facade", "Params", GH_ParamAccess.item)
        {
        }

        public override Guid ComponentGuid => new Guid("c0a7e6f1-2b3d-4a58-9e41-6d1f8b7c2a01");
        public override GH_Exposure Exposure => GH_Exposure.hidden;
    }
}
