using System.Collections.Generic;
using System.Linq;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade
{
    /// <summary>Base for facade components: category "Facade" and panel parameter helpers.</summary>
    public abstract class PanelComponent : GH_Component
    {
        protected PanelComponent(string name, string nick, string description, string subCategory)
            : base(name, nick, description, "Facade", subCategory)
        {
        }

        protected static int AddPanelInput(GH_InputParamManager pManager, string description, GH_ParamAccess access)
        {
            return pManager.AddParameter(new PanelParam(), "Panels", "P", description, access);
        }

        protected static List<Panel> GetPanels(IGH_DataAccess DA, int index)
        {
            var goos = new List<PanelGoo>();
            if (!DA.GetDataList(index, goos))
                return new List<Panel>();
            return goos.Where(g => g != null && g.Value != null).Select(g => g.Value).ToList();
        }
    }
}
